  (7, 'rolls', 'Лава с креветкой', '255 г. Креветка, творожный сыр, соус лава, рис, лист нори.', 530, null, 'real', null),
  (8, 'rolls', 'Лава с лососем', '245 г. Лосось, творожный сыр, соус лава, рис, лист нори.', 540, null, 'real', null),
