  (11, 'desserts', 'Чизкейк', '120 г. Классический десерт из творожного сыра с карамелизованной грушей и нотками маракуйи.', 270, null, 'real', null),
  (12, 'desserts', 'Морковный торт', '120 г. Нежный, пряный морковный бисквит с грушевой прослойкой и сливочным кремом из творожного сыра.', 270, null, 'real', null),
  (13, 'desserts', 'Молочная девочка с малиновым конфитюром', '120 г. Тающий, нежный торт из тонких, пропитанных сгущенным молоком коржей, прослойкой из легкого заварного крема и малинового крема. Украшен сочным, малиновым желе.', 270, 'milk-girl', 'real', null),
  (14, 'waffles', 'Вафля с сёмгой и яйцом пашот', '200 г. Бородинскую вафлю мы подаём с сёмгой, яйцом пашот и салатом из свежих овощей под пикантным сливочным соусом.', 550, 'waffle-salmon', 'real', 'center 85%'),
  (15, 'waffles', 'Вафля с беконом и яйцом пашот', '200 г. Сырную вафлю мы подаём с беконом, яйцом пашот и сливочно-чесночным соусом.', 430, 'waffle-bacon', 'real', 'center 80%'),
  (16, 'waffles', 'Вафля с жюльеном', '150 г. Классическую вафлю мы подаём с нежным жюльеном на основе копчёной курицы с грибами под сливочным соусом.', 410, 'waffle-julienne', 'real', null),
  (17, 'snacks', 'Жюльен с курицей и грибами', '120 г. Нежная горячая закуска на основе копчёной курицы с грибами, запечёнными со сливочным соусом под сырной корочкой.', 390, 'julienne', 'real', null),
  (18, 'snacks', 'Тёплый салат с печёными овощами', '170 г. Копчёное куриное филе, баклажаны, цукини, шампиньоны, сладкий перец, творожный сыр. Заправляем оливковым маслом с добавлением бальзамического уксуса.', 520, 'salad-baked-vegetables', 'real', null),
  (19, 'snacks', 'Тёплый салат с тигровыми креветками', '170 г. Тигровые креветки, запечённая в меду свёкла, томаты "Черри", апельсин, микс салата. Заправляем пикантным соусом на основе оливкового масла с добавлением бальзамического уксуса.', 570, 'salad-tiger-shrimp', 'real', null),
  (20, 'snacks', 'Мясной салат с печёным картофелем', '170 г. Запечённые картофельные дольки, поджаренный бекон, свежие томаты и яйцо пашот, пекинская капуста. Заправляем пикантным сливочно-горчичным соусом.', 550, 'salad-meat-potato', 'real', null),
  (21, 'snacks', 'Салат с бататом и шпинатом', '170 г. Шпинат, запечённые дольки батата, обжаренные шампиньоны, копчёное куриное филе, сыр "Фета", заправляем с горчичным соусом.', 480, 'salad-sweet-potato', 'real', null),
  (22, 'snacks', 'Салат с бейби картофелем и сёмгой', '170 г. Сёмга слабосоленая, томаты "Черри", авокадо, картофель бейби, сыр "Брынза", салат "Айсберг", заправляем с острым соусом "Шрирача".', 610, 'salad-salmon-potato', 'real', null),
  (23, 'snacks', 'Цезарь с сёмгой', '190 г. Сёмга слабосоленая, салат "Айсберг", пекинская капуста, перепелиные яйца, томаты "Черри", сыр "Пармезан", сухарики, сливочно-чесночный соус.', 605, 'caesar-salmon', 'real', null),
  (24, 'snacks', 'Цезарь с курицей', '190 г. Копчёное куриное филе, салат "Айсберг", пекинская капуста, перепелиные яйца, томаты "Черри", сыр "Пармезан", сухарики, сливочно-чесночный соус.', 465, 'caesar-chicken', 'real', null),
  (25, 'hot', 'Ризотто с морепродуктами', '300 г. Ризотто в сочетании с осьминогами, кальмарами, мидиями и сыром "Пармезан". Заправляем сливочно-томатным соусом.', 740, 'risotto-seafood', 'real', null),
  (26, 'hot', 'Ризотто с грибами', '280 г. Ризотто в сочетании с грибами и сыром "Пармезан". Особый аромат блюду придают белые грибы. Заправляем сливочным соусом с пряностями.', 610, 'risotto-mushrooms', 'real', null),
  (27, 'hot', 'Ризони с креветками', '170 г. Изысканная паста «орзо», тигровые креветки, заправляем ароматным сливочным соусом от шеф-повара.', 550, 'risoni-shrimp', 'real', null),
  (28, 'hot', 'Ризони с мидиями в сливочно-шпинатном соусе', '260 г. Паста "орзо", мидии, сливочно-шпинатный соус, дополняем сыром "Пармезан".', 530, null, 'real', null),
  (29, 'hot', 'Спагетти с курицей и кедровыми орехами', '280 г. Паста с копченым куриным филе, кедровым орехом, салатом "Руккола", сыром "Пармезан" в ароматном соусе "Песто".', 550, 'spaghetti-chicken', 'real', null),
  (30, 'hot', 'Карбонара', '280 г. Классическая паста с беконом, яичным желтком, сыром "Пармезан", салатом "Руккола" в сливочном соусе.', 495, 'carbonara', 'real', null),
  (31, 'hot', 'Паста с форелью и брокколи', '210 г. Паста с нежной сёмгой, брокколи, ароматным сливочно-сырным соусом. Украшаем микрозеленью.', 640, 'pasta-trout', 'real', null),
  (32, 'hot', 'Паста с копчёной курицей и шампиньонами', '210 г. Паста с копчёным куриным филе, шампиньонами, сырно-сливочным соусом и петрушкой.', 550, 'pasta-chicken', 'real', null),
  (33, 'hot', 'Лазанья с курицей и грибами', '270 г. Классическая лазанья с жюльеном из копчёной курицы и шампиньонов, сыром "Пармезан" и сливочным соусом.', 630, null, 'real', null),
  (34, 'hot', 'Суп Том Ям с креветкой', '240 г / 50 г. Знаменитый тайский суп с порцией королевских креветок, на основе куриного бульона с добавлением острой пасты TomYum, кокосового молока, имбиря, листа лайма, специй. Подаём с томатами "Черри", шампиньонами и порцией риса.', 430, 'tom-yum-shrimp', 'real', null),
  (35, 'hot', 'Суп Том Ям с курицей', '240 г / 50 г. Знаменитый тайский суп с порцией куриного филе, на основе куриного бульона с добавлением острой пасты TomYum, кокосового молока, имбиря, листа лайма, специй. Подаём с томатами "Черри", шампиньонами и порцией риса.', 365, null, 'real', null),
  (36, 'drinks', 'Морс клюквенный', '250 мл', 105, null, 'real', null);
